
/* Team-selected backgrounds: Home, Pokédex, Stats, Settings */
body.team-pattern-page{
background:var(--team-page-bg,#f5f5f5) !important;
}
body.team-pattern-page::before{
content:"";
position:fixed;
inset:0;
z-index:0;
pointer-events:none;
background-color:var(--team-page-bg,#f5f5f5);
background-image:var(--team-page-image,none);
background-repeat:repeat;
background-position:0 0;
background-size:920px 720px;
}
body.team-pattern-page::after{
content:"";
position:fixed;
inset:0;
z-index:1;
pointer-events:none;
background:var(--team-page-overlay,rgba(255,255,255,.10));
}
body.team-pattern-page > header,
body.team-pattern-page > main,
body.team-pattern-page > .public-banner{
position:relative;
z-index:2;
}
body.team-pattern-page #homePage,
body.team-pattern-page #dexPage,
body.team-pattern-page #statsPage,
body.team-pattern-page #settingsPage,
body.team-pattern-page #achievementsPage{
background:transparent !important;
}
