body.team-pattern-page[data-team="team-galactic"]::before{
background-color:#24103f;
background-image:
var(--team-page-image),
radial-gradient(circle at 14% 18%,rgba(180,105,255,.32) 0 10%,transparent 26%),
radial-gradient(circle at 78% 24%,rgba(92,61,190,.34) 0 12%,transparent 30%),
radial-gradient(circle at 62% 78%,rgba(210,91,210,.24) 0 10%,transparent 28%),
radial-gradient(circle at 26% 72%,rgba(74,45,145,.38) 0 14%,transparent 32%),
linear-gradient(135deg,#12071f 0%,#2d1450 38%,#4b1d67 67%,#180a2c 100%);
background-repeat:repeat,no-repeat,no-repeat,no-repeat,no-repeat,no-repeat;
background-position:0 0,center,center,center,center,center;
background-size:920px 720px,cover,cover,cover,cover,cover;
}
/* Bottom navigation follows the selected team on every signed-in page */
body[data-team] .bottom-nav{
background:var(--team-nav-bg) !important;
border-top:1px solid rgba(255,255,255,.16);
box-shadow:0 -5px 18px rgba(0,0,0,.16);
}
body[data-team] .bottom-nav .nav-btn{
color:var(--team-nav-text) !important;
}
body[data-team] .bottom-nav .nav-btn.active{
color:var(--team-nav-active) !important;
}
body[data-team] .bottom-nav .nav-btn.active .nav-icon{
filter:drop-shadow(0 0 5px currentColor);
}
@media(max-width:700px){
body.team-pattern-page::before{background-size:680px 532px}
body.team-pattern-page[data-team="team-galactic"]::before{background-size:680px 532px,cover,cover,cover,cover,cover}
}
